import "../../tokens/tokens.css";
import "./Button.css";

export interface ButtonProps {
  label: string;
  disabled?: boolean;
  onClick?: () => void;
}

export function Button({ label, disabled = false, onClick }: ButtonProps) {
  return (
    <button className="pg-button" disabled={disabled} onClick={onClick} type="button">
      {label}
    </button>
  );
}

.pg-button {
  background: var(--pg-action);
  border: 0;
  border-radius: 0.5rem;
  color: var(--pg-on-action);
  cursor: pointer;
  min-height: 2.75rem;
  padding: 0.75rem 1rem;
}

.pg-button:hover:not(:disabled) {
  background: var(--pg-action-hover);
}

.pg-button:focus-visible {
  outline: 3px solid var(--pg-focus);
  outline-offset: 2px;
}

.pg-button:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

import type { Meta, StoryObj } from "@storybook/react-vite";
import { fn } from "storybook/test";

import { Button } from "./Button";

const meta = {
  title: "Account/Button",
  component: Button,
  args: {
    label: "Continue",
    onClick: fn(),
  },
} satisfies Meta<typeof Button>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {};

export const Disabled: Story = {
  args: {
    disabled: true,
  },
};
